from 生成报告 import render
issues=[
('C',8,40,'收敛域应区分全体收敛点与任一收敛子域','任意限制D都可逐点收敛，但通常“收敛域”指共同定义域内的全部收敛点。','先固定共同定义域E，定义D={x∈E:序列/级数收敛}；若只是子集称在D收敛。','x^n可在{0}上收敛，却不能据此说其完整实收敛域只有{0}。'),
('C',96,106,'导数极限不存在不能写成两个已存在值不相等','右边导数函数列极限不存在，≠符号容易暗示两边都是实数。','写“导函数列不收敛，因而不能交换求导与极限”，例如在x=0处sqrt n→∞。','S_n本身由1/sqrt n一致趋0，此例正确说明一致收敛仍不足以保持导数极限。'),
('A',145,146,'Dirichlet双极限公式没有使用内层m','源式[cos(n!πx)]^2n仅指数2再乘n（或即使理解2n也没有m）；内层m极限不起作用。','改为lim_n lim_m [cos(n!πx)]^(2m)，必须将2m整体放入指数。','固定n，若n!x为整数则cos²=1，其2m次幂恒1，否则绝对值<1极限0；原x=0若按TeX得到n，外层发散。'),
('C',221,224,'内部一致收敛定义应限定区间域','任意D上的“每个闭区间⊂D”可能几乎没有约束，不等于一般紧集上的局部一致收敛。','本章把D限定为区间，或一般域改成每个紧子集K⊂D一致收敛。','D为离散无限集时只有单点退化区间，逐点收敛即可满足原条件；后文用于开区间的定义正确。'),
('A',237,250,'一致收敛例子的负值及严格号写错','第249行S_n(x)=|x/(1+n²x²)|对负x错误，≤写成<在x=±1/n失败，x=0还出现0/0。','保留第244—246行正确估计|S_n|≤1/(2n)，单独处理0，不改正确结论。','x=−1/n时S_n=−1/(2n)，不是绝对值；同处界达到等号。'),
('C',384,442,'Cauchy准则的p范围前后不统一','函数列写p>1但未说整数，级数版写p∈N（本笔记含0）。','统一p∈N且p≥1；允许p≥2也等价但需用共同远项补相邻项差，非整数索引无意义。','p=3/2使S_(n+p)未定义；p=0只给空和不影响有效范围。'),
('C',974,985,'函数列指标与划分段数复用n','先固定S_n，再要求划分恰有n段，并写所有划分求和到n，容易读成强制段数等于函数列索引。','固定S_N，划分用m段并求和i=1…m。','可积性保证存在某个有限段数划分，不保证预先指定N段满足任意小振幅和。正确逻辑不依赖同一索引。'),
('B',1374,1378,'比值收敛半径公式缺适用条件','a_(n+1)/a_n不是任意幂级数都定义且有极限，不能作为无条件替代定义。','明确an最终非零且绝对比值存在扩展实极限时使用；其他情况仍用limsup根式。','cos x系数含无限多个零，比值法未定义而收敛半径∞；稀疏幂级数同样需根式。'),
('C',1382,1391,'n=0首项0^0没有约定','Σ从0起n^n/n!的0^0尚未定义；说不影响收敛不能使原表达式自动有定义。','从n=1起，或明确令a0为任意指定有限常数。','n≥1的比值、Stirling端点及[−1/e,1/e)收敛域均正确。'),
('C',1432,1451,'Abel端点公式漏有限正半径及误加R^n','第二支需要0<R<∞，并写bn=anR^n后又出现ΣbnR^n。','第二支限定有限正R，正确因子为bn(x/R)^n；Σbn收敛用于Abel。','R=0时x/R无定义、R=∞不是实端点。第一支内部一致收敛不需要有限R。'),
('A',1683,1691,'Taylor积分余项中间微分漏负号','∫r_n″(t)(x−t)dt应=−1/2∫r_n″(t)d(x−t)²；源文写正号后又得正三阶积分，前后不相容。','在第1689行微分前补负号；边界项明确为[r_n′(t)(t−x)]而非固定r_n′(x0)。','d(x−t)²=−2(x−t)dt；分部后负号再反转，最终1/n!积分余项正确。'),
('B',1898,1923,'商级数递推尚未证明有正收敛半径','形式系数递推不自动说明所得级数收敛于f/g；b0≠0提供可补出的局部逆级数构造。','先取小半径使h=(g−b0)/b0的绝对系数和<1，以1/g=(1/b0)Σ(−h)^k构造并证明绝对收敛，再比较系数。','若只把递推看作形式运算，不能据此调用逐项运算；原tan到x5系数及e^x sin x计算均正确。'),
('B',2015,2040,'正弦乘积取对数比较系数需说明域与交换','实对数要求各因子为正且sin x/x>0；双和重排和系数提取未给收敛控制。','先限制|x|≤r<π，用Σ_n Σ_k (r²/(n²π²))^k/k≤C_r Σ1/n²<∞证明绝对一致收敛，再比较Taylor系数。','该控制由−ln(1−u)≤u/(1−u)得出；Basel值π²/6、π⁴/90正确，但当前文字缺此交换说明，并依赖第五章乘积公式。'),
('A',2067,2070,'广义二项式系数的指标范围和α=0漏项','写∀k∈R而所定义分母k!与有限乘积只支持非负整数；α∉Z+还可能包括0，其系数不是全非零。','取n∈N0，非终止版限制α∉N0；α为非负整数时有限二项式另列。','α=0,n=1时binom(0,1)=0，反驳所写非零；实k=1/2不属于已给的组合数定义。端点分类对合法非整数α正确。'),
('C',2072,2096,'多条级数求和下标误写变量x','1/(1+x)、1/(1−x)、1/(1±x²)的Σ下写x=0，求和体却用n。','统一Σ_(n=0)^∞；保留变量x。','按原符号n未被绑定、x又同时被求和与作为自变量，不能解释为规范级数。'),
('A',2077,2086,'平方根两条求和式漏x幂和符号','sqrt(1+x)第一求和缺(−1)^(k−1)x^k；1/sqrt(1+x)第一求和缺x^n。','补全部幂及符号，约定(−1)!!=0!!=1；随后展开式的系数本来正确。','x=0时平方根第一式变为1加正系数和>1；倒数第一式与x无关，不可能等于非恒定函数。'),
('A',2105,2107,'反正切表求和式错误','写Σ_(n=1)^∞ x^(2n+1)/(2n+1)!，缺线性项、交错号，且分母误为阶乘。','改Σ_(n=0)^∞(−1)^n x^(2n+1)/(2n+1)，收敛域[−1,1]正确。','原式0处导数0，而arctan′(0)=1；其系数x³/6也与正确−x³/3不同。'),
('C',2118,2127,'Bernstein多项式次数是至多n','一般f的Bn可能降次，X未在本定义绑定且n必须≥1。','写n为正整数、X=C[0,1]，Bn次数至多n。','f≡1时Bn=1次数0；f=t时Bn=x次数1。后面三个矩关系正确。'),
('C',2330,2333,'一致闭包定义漏一致收敛','“所有已知收敛的函数序列的极限”未说明收敛类型，会把逐点极限也纳入一致闭包。','明确B={f:存在fn∈A且fn在E上一致收敛到f}。','多项式x^n在[0,1]逐点极限不连续，不属于多项式的一致闭包；后面代数封闭证明采用的确是一致版本。'),
('B',2505,2512,'三角逼近应用需说明紧集是圆周','sin、cos在[0,2π]不能分离0和2π，不能直接以该闭区间套Stone–Weierstrass。','取K为单位圆（把周期端点识别），连续周期函数对应C(K)，坐标sin、cos在圆周上分离点且含1。','圆周版本所有前提满足，结论全R周期一致逼近正确；当前只写取代数而漏K和分离点的核验。'),
('C',2524,2661,'连续函数稠密须标明积分距离','此处仅∫|f−fk|→0，不能理解为上一节的一致稠密；原Riemann函数空间上这个量还是半距离。阶梯格子端点的点态估计也需避开下一段取值。','写“在积分半距离d(f,g)=∫|f−g|下稠密”；积分意义相等类取商后才为距离。第2571—2574行限定半开段，有限端点不影响积分。','跳跃阶跃函数不可能是连续函数的一致极限，但可被积分逼近；单点非零函数与零函数距离0。线性平滑和截断证明的积分界成立。'),
]
render(12,'函数项序列与函数项级数','已通读2778行、7节、全部数学环境和正文公式表。序列判别、一致Cauchy、M/Abel/Dirichlet、连续与可积保持、C¹逐项求导、Dini及两种Weierstrass证明主体成立。主要错误集中在Dirichlet双极限、Taylor中间符号和常用级数表；幂级数比值、商运算、乘积系数及三角逼近应用缺条件或补证。',[(1,182,'12.1 点态收敛','x^n双极限、导数反例、阶乘格点、nx(1−x²)^n积分反例通过；Dirichlet双极限式错误。'),(183,383,'12.2 一致概念和判别','sup判据、移动点列反证、指数序列局部一致证明通过；绝对值估计一行和内部域需明确。'),(384,610,'12.2 Cauchy与A-D','三个判别和证明成立，p整数范围不统一；α>1指数项M判别正确。'),(611,1011,'12.3 连续与积分','连续端点、几何逐项积分和对数收敛域、Riemann可积保持均通过，划分段数需换指标。'),(1012,1272,'12.3 求导与Dini','C¹求导交换证明成立；Dini允许每个x的单调方向不同，绝对误差仍递减。级数版仅陈述。'),(1273,1454,'12.4 半径与Abel','Cauchy–Hadamard的limsup发散子列证明正确；零/无穷半径已单独处理；比值式及Abel端点范围需补。'),(1455,1533,'12.4 连续和运算','内部/端点连续及闭子区间积分成立，导数半径保持与逐项求导证明通过。'),(1534,1710,'12.5 解析与余项','平坦函数反例正确，积分余项最终式正确但中间负号错；Lagrange/Cauchy余项仅正文陈述。'),(1711,2014,'12.5 展开方法和例子','指数、双曲、几何、对数、反正切、平移、e^x sin x、tan、ln(sin x/x)系数正确；商收敛需证明。'),(2015,2116,'12.5 乘积及公式表','Basel推论结论正确但交换域需补；二项式指标、根式求和、arctan求和与多处下标错误。'),(2117,2319,'12.6 Bernstein与Weierstrass','矩关系、正算子估计、卷积多项式及绝对值零常项逼近通过；次数和定义变量需改。'),(2320,2512,'12.6 Stone–Weierstrass','一致闭代数、两点插值及四步格逼近通过；闭包定义漏一致性，三角应用须取圆周。'),(2513,2778,'12.7 可积逼近','阶梯—线性平滑—积分三角界及截断不增误差均成立；稠密性是积分半距离，端点点态估计不影响积分。')],issues,'''### 证明状态与反例复核
第1103行级数逐项求导、第1245行级数Dini、第1344行重复的半径定理只有陈述，分别可由部分和、前一命题直接推出，本轮不补写。正文中的Lagrange/Cauchy余项和二项式、arcsin展开表并未逐项写证明；正确表项也不应称为已有完整证明。常用表tan展开需注明|x|<π/2，保留与有限阶展开的区别。

第1470行先引用arctan展开，后面第1793行才证明，可视为前向引用，无循环：后证只由几何级数积分得出。ln在x=1的值需使用此前Abel端点连续性，不能直接以几何级数在[0,1]一致收敛为由；本章已有足够依据。Cauchy–Hadamard明确取无穷多个坏n，避免了第五章把limsup当所有尾项下界的问题。

第2382行两点插值没有偷偷要求常函数1属于代数：u=(g−g(x1))k=gk−g(x1)k、v同理，乘法和数乘闭性足够。第三步y=x时只需用不消失函数作一次缩放，属可直接补出的省略。Stone–Weierstrass证明以紧集K上的相对开覆盖理解邻域，四步max/min方向正确。

第2259行Bernoulli界在|x|≤1上成立，卷积核尾界取0<δ<1即可；这属于显然可选的小半径。可积函数平滑选择δ同时小于相邻格子宽度的一半，m=1无需平滑，B=0截断取零函数，这些边界可直接覆盖，未计为结论错误。本章无外部正文图片。''',unproved=(1103,1245,1344,2510))
